// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;

    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }

    function testFuzz_property(uint256 selector) public {
        uint256 idx = bound(selector, 0, 2);
        bytes32 role;
        if (idx == 0) {
            role = c.PROPOSER_ROLE();
        } else if (idx == 1) {
            role = c.EXECUTOR_ROLE();
        } else {
            role = c.TIMELOCK_ADMIN_ROLE();
        }
        bytes32 admin = c.TIMELOCK_ADMIN_ROLE();
        assertTrue(c.getRoleAdmin(role) == admin, "admin role mapping violated");
    }
}
